<template><section class="page"><header><div><h1 class="page-title">App 免费体验课管理</h1><p class="page-description">管理引流课任务及其关联小节。</p></div><el-button type="primary" @click="edit()">新增体验课任务</el-button></header><div class="filters"><el-select v-model="project" clearable placeholder="全部项目"><el-option label="临床" value="临床"/><el-option label="中级职称" value="中级职称"/></el-select><el-radio-group v-model="status"><el-radio-button label="ON">使用中</el-radio-button><el-radio-button label="OFF">已下架</el-radio-button><el-radio-button label="ALL">全部</el-radio-button></el-radio-group></div><el-table :data="visible"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="name" label="任务名称" min-width="200"/><el-table-column prop="apps" label="显示应用" min-width="180"/><el-table-column prop="project" label="项目" width="130"/><el-table-column prop="profession" label="专业" width="160"/><el-table-column prop="period" label="开放时间" width="190"/><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag :type="s.row.status==='ON'?'success':'info'">{{s.row.status==='ON'?'启用':'已下架'}}</el-tag></template></el-table-column><el-table-column label="操作" width="250"><template slot-scope="s"><el-button type="text" @click="sections(s.row)">关联小节</el-button><el-button type="text" @click="edit(s.row)">编辑</el-button><el-button type="text" @click="s.row.status=s.row.status==='ON'?'OFF':'ON'">{{s.row.status==='ON'?'下架':'上架'}}</el-button></template></el-table-column></el-table><el-dialog :title="current?'编辑体验课任务':'新增体验课任务'" :visible.sync="dialog" width="650px"><el-form label-width="100px"><el-form-item label="显示应用"><el-checkbox-group v-model="draft.apps"><el-checkbox label="昭昭医考 App"/><el-checkbox label="昭昭医考小程序"/></el-checkbox-group></el-form-item><el-form-item label="任务名称"><el-input v-model="draft.name"/></el-form-item><el-form-item label="项目"><el-select v-model="draft.project"><el-option label="临床" value="临床"/><el-option label="中级职称" value="中级职称"/></el-select></el-form-item><el-form-item label="专业"><el-input v-model="draft.profession"/></el-form-item><el-form-item label="开放时间"><el-date-picker v-model="draft.periodValue" type="datetimerange" range-separator="至"/></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></span></el-dialog><el-dialog title="关联小节" :visible.sync="sectionDialog" width="720px"><el-input v-model="sectionKeyword" clearable placeholder="搜索小节名称或 ID"/><el-table :data="filteredSections" @selection-change="selectedSections=$event"><el-table-column type="selection" width="48"/><el-table-column prop="id" label="小节 ID" width="100"/><el-table-column prop="name" label="小节名称"/><el-table-column prop="subject" label="所属科目" width="160"/></el-table><span slot="footer"><el-button @click="sectionDialog=false">取消</el-button><el-button type="primary" @click="saveSections">确认关联</el-button></span></el-dialog></section></template>
<script>export default{data:()=>({project:'',status:'ON',dialog:false,sectionDialog:false,current:null,sectionKeyword:'',selectedSections:[],draft:{apps:[],name:'',project:'',profession:'',periodValue:[]},rows:[{id:6,name:'新用户限免',apps:'昭昭医考 App、昭昭医考小程序',project:'临床',profession:'临床执业医师',period:'2026-01-01 至 11-14',status:'ON',sections:[]},{id:14,name:'精华体验课',apps:'昭昭医考 App',project:'中级职称',profession:'肾内主治',period:'2026-01-01 至 12-31',status:'ON',sections:[]}],sectionRows:[{id:58466,name:'第一单元 中医学理论体系',subject:'中医基础理论'},{id:58469,name:'第二单元 中药的性能',subject:'中药学'},{id:58567,name:'第四单元 和解剂',subject:'方剂学'}]}),computed:{visible(){return this.rows.filter(x=>(!this.project||x.project===this.project)&&(this.status==='ALL'||x.status===this.status))},filteredSections(){const q=this.sectionKeyword.toLowerCase();return this.sectionRows.filter(x=>!q||(x.name+x.id).toLowerCase().includes(q))}},methods:{edit(x){this.current=x||null;this.draft=x?{...x,apps:x.apps.split('、'),periodValue:[]}:{apps:['昭昭医考 App'],name:'',project:'临床',profession:'',periodValue:[]};this.dialog=true},save(){if(!this.draft.name||!this.draft.apps.length)return this.$message.warning('请填写任务名称并选择显示应用');if(this.current)Object.assign(this.current,this.draft,{apps:this.draft.apps.join('、')});else this.rows.push({...this.draft,id:Math.max(...this.rows.map(x=>x.id))+1,apps:this.draft.apps.join('、'),period:'待配置',status:'OFF',sections:[]});this.dialog=false;this.$message.success('任务已保存')},sections(x){this.current=x;this.selectedSections=x.sections||[];this.sectionDialog=true},saveSections(){this.current.sections=this.selectedSections;this.sectionDialog=false;this.$message.success(`已关联 ${this.selectedSections.length} 个小节`)}}}</script>
<style scoped>.page{max-width:1440px;margin:auto}.page>header{display:flex;justify-content:space-between;align-items:flex-end}.filters{display:flex;gap:12px;margin:24px 0}.filters .el-select{width:220px}</style>
